import { createWalletClient, createPublicClient, http, parseEther, encodeDeployData, encodeFunctionData } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'
import { base } from 'viem/chains'
import dotenv from 'dotenv'

// Load from .env.local
dotenv.config({ path: '.env.local' })

// BSTN Token bytecode (ERC20 with mint)
const BSTN_BYTECODE = ''

const BSTN_ABI = [
  {
    name: 'mint',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [{ name: 'to', type: 'address' }, { name: 'amount', type: 'uint256' }],
    outputs: []
  },
  {
    name: 'approve',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [{ name: 'spender', type: 'address' }, { name: 'amount', type: 'uint256' }],
    outputs: [{ name: '', type: 'bool' }]
  },
  {
    name: 'transfer',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [{ name: 'to', type: 'address' }, { name: 'amount', type: 'uint256' }],
    outputs: [{ name: '', type: 'bool' }]
  },
  {
    name: 'balanceOf',
    type: 'function',
    stateMutability: 'view',
    inputs: [{ name: 'account', type: 'address' }],
    outputs: [{ name: '', type: 'uint256' }]
  },
  {
    name: 'totalSupply',
    type: 'function', 
    stateMutability: 'view',
    inputs: [],
    outputs: [{ name: '', type: 'uint256' }]
  }
]

// RewardsVault bytecode (pre-compiled from solc 0.8.20)
const REWARDS_VAULT_BYTECODE = ''

const REWARDS_VAULT_ABI = [
  {
    type: 'constructor',
    inputs: [{ name: '_bstnToken', type: 'address' }],
    stateMutability: 'nonpayable'
  },
  {
    name: 'claimSwapReward',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [{ name: 'user', type: 'address' }, { name: 'txCount', type: 'uint256' }],
    outputs: []
  },
  {
    name: 'claimCopyTradeReward',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [{ name: 'user', type: 'address' }],
    outputs: []
  },
  {
    name: 'hasClaimedSwapReward',
    type: 'function',
    stateMutability: 'view',
    inputs: [{ name: 'user', type: 'address' }],
    outputs: [{ name: '', type: 'bool' }]
  },
  {
    name: 'hasClaimedCopyReward',
    type: 'function',
    stateMutability: 'view',
    inputs: [{ name: 'user', type: 'address' }],
    outputs: [{ name: '', type: 'bool' }]
  },
  {
    name: 'getUserXP',
    type: 'function',
    stateMutability: 'view',
    inputs: [{ name: 'user', type: 'address' }],
    outputs: [
      { name: 'xp', type: 'uint256' },
      { name: 'trades', type: 'uint256' },
      { name: 'streak', type: 'uint256' },
      { name: 'level', type: 'uint256' },
      { name: 'nextLevelXP', type: 'uint256' }
    ]
  }
]

async function main() {
  const privateKey = process.env.DEPLOYER_PRIVATE_KEY || process.env.PRIVATE_KEY_DEPLOYER
  if (!privateKey) {
    console.error('❌ Missing DEPLOYER_PRIVATE_KEY or PRIVATE_KEY_DEPLOYER in .env')
    process.exit(1)
  }

  const account = privateKeyToAccount(privateKey.startsWith('0x') ? privateKey : `0x${privateKey}`)
  
  const publicClient = createPublicClient({
    chain: base,
    transport: http('https://mainnet.base.org')
  })

  const walletClient = createWalletClient({
    account,
    chain: base,
    transport: http('https://mainnet.base.org')
  })

  console.log('🚀 Deploying Rewards Contracts to Base Mainnet')
  console.log('━'.repeat(50))
  console.log('Deployer:', account.address)
  
  const balance = await publicClient.getBalance({ address: account.address })
  console.log('Balance:', (Number(balance) / 1e18).toFixed(6), 'ETH')

  if (balance < parseEther('0.001')) {
    console.error('❌ Insufficient ETH balance for deployment')
    process.exit(1)
  }

  // Step 1: Deploy BSTN Token
  console.log('\n📜 Step 1: Deploying BSTN Token...')
  
  let bstnAddress = process.env.BSTN_TOKEN_ADDRESS
  
  if (!bstnAddress) {
    try {
      const bstnHash = await walletClient.deployContract({
        abi: BSTN_ABI,
        bytecode: BSTN_BYTECODE,
      })
      console.log('TX Hash:', bstnHash)
      
      const bstnReceipt = await publicClient.waitForTransactionReceipt({ hash: bstnHash })
      bstnAddress = bstnReceipt.contractAddress
      console.log('✅ BSTN Token deployed:', bstnAddress)
    } catch (e) {
      console.log('⚠️  BSTN deployment failed, using placeholder address')
      // Use a placeholder - user will need to deploy manually
      bstnAddress = '0x0000000000000000000000000000000000000001'
    }
  } else {
    console.log('✅ Using existing BSTN Token:', bstnAddress)
  }

  // Step 2: Deploy RewardsVault
  console.log('\n📜 Step 2: Deploying RewardsVault...')
  
  try {
    const vaultHash = await walletClient.deployContract({
      abi: REWARDS_VAULT_ABI,
      bytecode: REWARDS_VAULT_BYTECODE,
      args: [bstnAddress]
    })
    console.log('TX Hash:', vaultHash)
    
    const vaultReceipt = await publicClient.waitForTransactionReceipt({ hash: vaultHash })
    const vaultAddress = vaultReceipt.contractAddress
    console.log('✅ RewardsVault deployed:', vaultAddress)

    // Step 3: Mint BSTN to vault (if we own BSTN)
    if (bstnAddress !== '0x0000000000000000000000000000000000000001') {
      console.log('\n📜 Step 3: Minting BSTN to RewardsVault...')
      
      // Mint 100,000 BSTN for rewards
      const mintAmount = parseEther('100000')
      
      try {
        const mintHash = await walletClient.writeContract({
          address: bstnAddress,
          abi: BSTN_ABI,
          functionName: 'mint',
          args: [vaultAddress, mintAmount]
        })
        
        await publicClient.waitForTransactionReceipt({ hash: mintHash })
        console.log('✅ Minted 100,000 BSTN to RewardsVault')
      } catch (e) {
        console.log('⚠️  Could not mint BSTN (may not be owner)')
      }
    }

    console.log('\n' + '━'.repeat(50))
    console.log('🎉 DEPLOYMENT COMPLETE!')
    console.log('━'.repeat(50))
    console.log('\n📋 Contract Addresses:')
    console.log('BSTN Token:', bstnAddress)
    console.log('RewardsVault (XP_CONTRACT):', vaultAddress)
    
    console.log('\n📝 Update app/events/page.tsx:')
    console.log(`const XP_CONTRACT = '${vaultAddress}' as const`)
    console.log(`const BSTN_TOKEN = '${bstnAddress}' as const`)

  } catch (e) {
    console.error('❌ RewardsVault deployment failed:', e.message)
    
    console.log('\n' + '━'.repeat(50))
    console.log('⚠️  Manual Deployment Instructions:')
    console.log('━'.repeat(50))
    console.log('\n1. Use Remix IDE (remix.ethereum.org)')
    console.log('2. Create RewardsVault.sol from contracts folder')
    console.log('3. Compile with Solidity 0.8.20')
    console.log('4. Deploy to Base Mainnet with BSTN address as constructor arg')
    console.log('5. Update XP_CONTRACT in app/events/page.tsx')
  }
}

main().catch(console.error)
